public class AsyncBoundaryProbe {
 public static Integer runs=0;
 public class ProbeException extends Exception {}
 public class FaultJob implements Queueable, Finalizer {
  private String mode;
  public FaultJob(String m){mode=m;}
  public void execute(QueueableContext context){
   System.attachFinalizer(this);
   if(mode=='custom') throw new ProbeException('owned custom marker');
   if(mode=='list'){List<Integer> items=new List<Integer>();Integer ignored=items[0];}
  }
  public void execute(FinalizerContext context){
   Exception error=context.getException();
   Map<String,Object> data=new Map<String,Object>{'result'=>String.valueOf(context.getResult()),'nullException'=>error==null};
   if(error!=null){data.put('type',error.getTypeName());data.put('message',error.getMessage());data.put('custom',error instanceof ProbeException);data.put('stackNonempty',String.isNotBlank(error.getStackTraceString()));}
   insert new Account(Name='owned-native-finalizer-'+mode,Description=JSON.serialize(data));
  }
 }
 public class ChainNode implements Queueable,Finalizer {
  private Integer step;
  public ChainNode(Integer n){step=n;}
  public void execute(QueueableContext context){
   System.attachFinalizer(this);
   runs++;
   insert new Account(Name='owned-native-chain-'+step,Description=String.valueOf(System.isQueueable()));
  }
  public void execute(FinalizerContext context){
   if(step==1){AsyncOptions options=new AsyncOptions();options.MaximumQueueableStackDepth=2;System.enqueueJob(new ChainNode(2),options);}
  }
 }
 @future public static void spawnFromFuture(){
  AsyncOptions options=new AsyncOptions();options.MaximumQueueableStackDepth=2;
  System.enqueueJob(new ChainNode(1),options);
 }
}

